import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:archive/archive.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:qchat/features/miniapps_host/miniapp_installer.dart';
import 'package:qchat/features/miniapps_host/miniapp_package.dart';

/// The committed fixtures are generated by
/// `pnpm --filter @qchat/miniapp-compiler fixture:miniapp` with a fixed Ed25519
/// seed. They are signed by a test key that is deliberately absent from
/// [miniAppTrustedPackageKeys]; every test that verifies passes it explicitly.
Uint8List fixture(String version) =>
    File('test/fixtures/miniapp/fixture-$version.qxpkg').readAsBytesSync();

Map<String, String> trustedKeys() {
  final key = jsonDecode(
    File('test/fixtures/miniapp/fixture-key.json').readAsStringSync(),
  ) as Map<String, Object?>;
  return <String, String>{
    key['keyId']! as String: key['publicKeyBase64']! as String,
  };
}

/// Rebuild a ZIP with one entry replaced. The re-encoded archive is a valid ZIP
/// (so the CRC layer passes) whose content no longer matches the manifest.
Uint8List rewritePackage(
  Uint8List bytes,
  String path,
  Uint8List content,
) {
  final source = ZipDecoder().decodeBytes(bytes, verify: true);
  final archive = Archive();
  for (final file in source.files) {
    if (!file.isFile) continue;
    archive.add(
      file.name == path
          ? ArchiveFile.bytes(path, content)
          : ArchiveFile.bytes(file.name, file.content),
    );
  }
  return Uint8List.fromList(ZipEncoder().encodeBytes(archive));
}

Future<String> errorCode(Future<Object?> future) async {
  try {
    await future;
  } on MiniAppPackageError catch (error) {
    return error.code;
  }
  fail('expected MiniAppPackageError');
}

void main() {
  const runtimeVersion = '1.0.0';

  test('the fixture verifies and exposes the compiled view bundle', () async {
    final package = await verifyMiniAppPackage(
      fixture('1.0.0'),
      runtimeVersion: runtimeVersion,
      trustedKeys: trustedKeys(),
    );

    expect(package.manifest.appId, 'qchat.fixture');
    expect(package.manifest.version, '1.0.0');
    expect(package.manifest.name, 'Fixture');
    expect(package.manifest.entry, 'pages/index/index');
    expect(package.manifest.pages, ['pages/index/index']);
    expect(package.manifest.qxColorScheme, 'light');
    expect(package.manifest.keyId, 'fixture-test-key');
    expect(
      package.manifest.files.map((file) => file.path),
      containsAll(<String>[
        'app.js',
        'app.json',
        'pages/index/index.js',
        'pages/index/index.wxml',
        'build/view.json',
      ]),
    );

    final bundle =
        jsonDecode(utf8.decode(package.viewBundle)) as Map<String, Object?>;
    expect(bundle['format'], 'qchat-view-bundle');
    expect(
      (bundle['pages']! as Map<String, Object?>).keys,
      contains('pages/index/index'),
    );
  });

  test('an unknown key id is refused, never treated as the only key', () async {
    expect(miniAppTrustedPackageKeys, isEmpty);
    expect(
      await errorCode(
        verifyMiniAppPackage(
          fixture('1.0.0'),
          runtimeVersion: runtimeVersion,
        ),
      ),
      'PACKAGE_SIGNATURE_INVALID',
    );
  });

  test('a package signed by another key is refused', () async {
    final key = trustedKeys();
    final other = <String, String>{
      key.keys.first: base64Encode(List<int>.filled(32, 7)),
    };
    expect(
      await errorCode(
        verifyMiniAppPackage(
          fixture('1.0.0'),
          runtimeVersion: runtimeVersion,
          trustedKeys: other,
        ),
      ),
      'PACKAGE_SIGNATURE_INVALID',
    );
  });

  test('a file edited after signing fails its manifest hash', () async {
    final tampered = rewritePackage(
      fixture('1.0.0'),
      'app.js',
      Uint8List.fromList(utf8.encode('App({ hacked: true });')),
    );
    expect(
      await errorCode(
        verifyMiniAppPackage(
          tampered,
          runtimeVersion: runtimeVersion,
          trustedKeys: trustedKeys(),
        ),
      ),
      'PACKAGE_HASH_MISMATCH',
    );
  });

  test('an edited manifest fails the signature', () async {
    final source = ZipDecoder().decodeBytes(fixture('1.0.0'), verify: true);
    final manifestFile = source.files.firstWhere(
      (file) => file.name == 'manifest.json',
    );
    final manifest =
        jsonDecode(utf8.decode(manifestFile.content)) as Map<String, Object?>;
    manifest['name'] = 'Edited';
    final tampered = rewritePackage(
      fixture('1.0.0'),
      'manifest.json',
      Uint8List.fromList(utf8.encode(jsonEncode(manifest))),
    );
    expect(
      await errorCode(
        verifyMiniAppPackage(
          tampered,
          runtimeVersion: runtimeVersion,
          trustedKeys: trustedKeys(),
        ),
      ),
      'PACKAGE_SIGNATURE_INVALID',
    );
  });

  test('a package that needs a newer runtime is refused', () async {
    expect(
      await errorCode(
        verifyMiniAppPackage(
          fixture('1.0.0'),
          runtimeVersion: '0.0.9',
          trustedKeys: trustedKeys(),
        ),
      ),
      'PACKAGE_FORMAT_UNSUPPORTED',
    );
  });

  test('an unsafe path is refused before anything is written', () async {
    // Renaming one entry to a traversal keeps the ZIP readable; the path check
    // runs before the manifest is even parsed.
    final source = ZipDecoder().decodeBytes(fixture('1.0.0'), verify: true);
    final archive = Archive();
    for (final file in source.files) {
      if (!file.isFile) continue;
      archive.add(
        ArchiveFile.bytes(
          file.name == 'app.js' ? '../escape.js' : file.name,
          file.content,
        ),
      );
    }
    final bytes = Uint8List.fromList(ZipEncoder().encodeBytes(archive));
    expect(
      await errorCode(
        verifyMiniAppPackage(
          bytes,
          runtimeVersion: runtimeVersion,
          trustedKeys: trustedKeys(),
        ),
      ),
      'PACKAGE_UNSAFE_PATH',
    );
  });

  test('canonical JSON sorts keys and keeps no whitespace', () {
    expect(
      canonicalJson(<String, Object?>{
        'b': 1,
        'a': <Object?>['x', true, null],
      }),
      '{"a":["x",true,null],"b":1}',
    );
  });

  test('package paths are relative and never traverse', () {
    expect(isSafePackagePath('pages/index/index.js'), isTrue);
    expect(isSafePackagePath('build/view.json'), isTrue);
    expect(isSafePackagePath('../app.js'), isFalse);
    expect(isSafePackagePath('/app.js'), isFalse);
    expect(isSafePackagePath('a//b.js'), isFalse);
    expect(isSafePackagePath(r'a\b.js'), isFalse);
    expect(isSafePackagePath('C:/app.js'), isFalse);
    expect(isSafePackagePath('a/./b.js'), isFalse);
  });

  test('only allowlisted extensions ship', () {
    expect(isAllowedPackageFile('app.js'), isTrue);
    expect(isAllowedPackageFile('build/view.json'), isTrue);
    expect(isAllowedPackageFile('icon.png'), isTrue);
    expect(isAllowedPackageFile('native.so'), isFalse);
    expect(isAllowedPackageFile('run.exe'), isFalse);
    expect(isAllowedPackageFile('lib.zip'), isFalse);
    expect(isAllowedPackageFile('.hidden.js'), isFalse);
  });

  test('semver comparison follows the numeric segments', () {
    expect(compareMiniAppVersions('1.10.0', '1.9.9'), greaterThan(0));
    expect(compareMiniAppVersions('1.0.0', '1.0.0'), 0);
    expect(compareMiniAppVersions('0.9.0', '1.0.0'), lessThan(0));
    expect(satisfiesRuntimeVersion('0.1.0', '1.0.0'), isTrue);
    expect(satisfiesRuntimeVersion('1.0.0', '1.0.0'), isTrue);
    expect(satisfiesRuntimeVersion('1.1.0', '1.0.0'), isFalse);
  });
}
